<?php

namespace Tests\Unit;

use App\Services\CampaignRules as R;
use App\Support\ApiException;
use App\Support\Json;
use PHPUnit\Framework\TestCase;

/**
 * Replays tests/fixtures/campaign-rules.json, generated by tests/fixtures/gen-campaign-rules.js from the ORIGINAL
 * server/campaigns.js, and requires the PHP port to return exactly the same values (or the same error code).
 */
/** Epoch milliseconds helper (UTC). */
final class Date
{
    public static function utc(int $y, int $m, int $d, int $h, int $min): int
    {
        return gmmktime($h, $min, 0, $m, $d, $y) * 1000;
    }
}

class CampaignRulesTest extends TestCase
{
    private static array $fx;

    public static function setUpBeforeClass(): void
    {
        self::$fx = json_decode(file_get_contents(__DIR__.'/../fixtures/campaign-rules.json'), true);
    }

    /** JSON round trip so ints/floats and list/map shapes compare the way the API would serialise them. */
    private static function norm(mixed $v): string
    {
        return json_encode($v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRESERVE_ZERO_FRACTION);
    }

    public function test_fixtures_are_present_and_non_trivial(): void
    {
        foreach (['localParts' => 50, 'zoned' => 30, 'nextRun' => 500, 'afterQuiet' => 500, 'inSegment' => 30, 'pick' => 5, 'clean' => 50, 'reachable' => 5] as $k => $min) {
            $this->assertGreaterThanOrEqual($min, count(self::$fx[$k]), $k);
        }
    }

    public function test_local_parts_match_node_intl(): void
    {
        foreach (self::$fx['localParts'] as $c) {
            if ($c['tzSensitive']) {
                continue; // covered by the invariant test below
            }
            $this->assertSame(self::norm($c['result']), self::norm(R::localParts($c['ts'], $c['tz'])), "{$c['tz']} @ {$c['ts']}");
        }
    }

    public function test_zoned_wall_clock_to_epoch_matches_node_around_dst_changes(): void
    {
        foreach (self::$fx['zoned'] as $c) {
            if ($c['tzSensitive']) {
                continue;
            }
            $this->assertSame($c['result'], R::zoned(...$c['args']), json_encode($c['args']));
        }
    }

    public function test_next_run_matches_node(): void
    {
        foreach (self::$fx['nextRun'] as $c) {
            if ($c['tzSensitive']) {
                continue;
            }
            $this->assertSame($c['result'], R::nextRun($c['schedule'], $c['after']), self::norm($c['schedule']).' after '.$c['after']);
        }
    }

    public function test_quiet_hours_match_node(): void
    {
        foreach (self::$fx['afterQuiet'] as $c) {
            if ($c['tzSensitive']) {
                continue;
            }
            $this->assertSame($c['result'], R::afterQuiet($c['ts'], $c['quiet'], $c['tz']), self::norm($c));
        }
    }

    /**
     * Node (ICU) and PHP ship different tz database releases, and Morocco's rules after mid-2026 differ between them. For those
     * cases the exact instant is not comparable, so the properties that must hold with ANY tz database are checked instead.
     */
    public function test_tz_sensitive_cases_keep_their_invariants(): void
    {
        $checked = 0;
        foreach (self::$fx['zoned'] as $c) {
            if (! $c['tzSensitive']) {
                continue;
            }
            [$y, $m, $d, $hh, $mm, $tz] = $c['args'];
            $p = R::localParts(R::zoned(...$c['args']), $tz);
            $this->assertSame([$y, $m, $d], [$p['y'], $p['m'], $p['d']], json_encode($c['args']));
            // (an hour that does not exist, e.g. skipped by a clock change, may land one hour later: allow that)
            $this->assertContains($p['h'] * 60 + $p['min'], [$hh * 60 + $mm, ($hh * 60 + $mm + 60) % 1440, ($hh * 60 + $mm + 1380) % 1440], json_encode($c['args']));
            $checked++;
        }
        foreach (self::$fx['nextRun'] as $c) {
            if (! $c['tzSensitive'] || $c['result'] === null) {
                continue;
            }
            $s = $c['schedule'];
            $next = R::nextRun($s, $c['after']);
            if ($next === null) {
                continue; // ended differently because the clock differs by an hour: only "> after" matters when it exists
            }
            $this->assertGreaterThan($c['after'], $next);
            $p = R::localParts($next, $s['tz']);
            $this->assertSame($s['time'], sprintf('%02d:%02d', $p['h'], $p['min']), json_encode($s));
            if ($s['freq'] === 'weekly') {
                $this->assertContains($p['dow'], $s['days']);
            }
            if ($s['freq'] === 'monthly') {
                $this->assertSame($s['dayOfMonth'], $p['d']);
            }
            $this->assertLessThanOrEqual(400, ($next - $c['after']) / 86400000);
            $checked++;
        }
        foreach (self::$fx['afterQuiet'] as $c) {
            if (! $c['tzSensitive'] || ! $c['quiet']) {
                continue;
            }
            $out = R::afterQuiet($c['ts'], $c['quiet'], $c['tz']);
            $this->assertGreaterThanOrEqual($c['ts'], $out);
            $this->assertLessThanOrEqual($c['ts'] + 24 * 3600000, $out);
            [$fh, $fm] = array_map('intval', explode(':', $c['quiet']['from']));
            [$th, $tm] = array_map('intval', explode(':', $c['quiet']['to']));
            $p = R::localParts($out, $c['tz']);
            $now = $p['h'] * 60 + $p['min'];
            $from = $fh * 60 + $fm;
            $to = $th * 60 + $tm;
            if ($from !== $to) {
                $inside = $from < $to ? ($now >= $from && $now < $to) : ($now >= $from || $now < $to);
                $this->assertFalse($inside, 'the result must be outside the quiet window: '.json_encode($c));
            }
            $checked++;
        }
        $this->assertGreaterThan(50, $checked);
    }

    public function test_fixed_zone_facts_that_never_depend_on_the_tz_database_release(): void
    {
        // UTC and India have no clock changes; Paris and New York follow stable EU/US rules.
        $this->assertSame(Date::utc(2026, 6, 15, 9, 0), R::zoned(2026, 6, 15, 9, 0, 'UTC'));
        $this->assertSame(Date::utc(2026, 6, 15, 3, 30), R::zoned(2026, 6, 15, 9, 0, 'Asia/Kolkata'));
        $this->assertSame(Date::utc(2026, 7, 1, 7, 0), R::zoned(2026, 7, 1, 9, 0, 'Europe/Paris'));   // CEST, UTC+2
        $this->assertSame(Date::utc(2026, 1, 15, 8, 0), R::zoned(2026, 1, 15, 9, 0, 'Europe/Paris')); // CET,  UTC+1
        $this->assertSame(Date::utc(2026, 7, 1, 13, 0), R::zoned(2026, 7, 1, 9, 0, 'America/New_York'));
        // quiet window 22:00-08:00 pushes 23:00 to 08:00 the next morning, and leaves 12:00 alone
        $q = ['from' => '22:00', 'to' => '08:00'];
        $this->assertSame(Date::utc(2026, 6, 16, 8, 0), R::afterQuiet(Date::utc(2026, 6, 15, 23, 0), $q, 'UTC'));
        $this->assertSame(Date::utc(2026, 6, 15, 8, 0), R::afterQuiet(Date::utc(2026, 6, 15, 3, 0), $q, 'UTC'));
        $this->assertSame(Date::utc(2026, 6, 15, 12, 0), R::afterQuiet(Date::utc(2026, 6, 15, 12, 0), $q, 'UTC'));
        // monthly on the 28th, weekly Mon/Wed, and "strictly after"
        $this->assertSame(Date::utc(2026, 6, 28, 10, 0), R::nextRun(['freq' => 'monthly', 'time' => '10:00', 'dayOfMonth' => 28, 'days' => [], 'tz' => 'UTC'], Date::utc(2026, 6, 15, 0, 0)));
        $this->assertSame(Date::utc(2026, 6, 17, 9, 0), R::nextRun(['freq' => 'weekly', 'time' => '09:00', 'days' => [1, 3], 'dayOfMonth' => 1, 'tz' => 'UTC'], Date::utc(2026, 6, 15, 9, 0))); // Mon 15th 09:00 itself is excluded
        $this->assertNull(R::nextRun(['freq' => 'daily', 'time' => '09:00', 'days' => [], 'dayOfMonth' => 1, 'tz' => 'UTC', 'endAt' => Date::utc(2026, 6, 1, 0, 0)], Date::utc(2026, 6, 15, 0, 0)));
    }

    public function test_segments_audience_and_reachability_match_node(): void
    {
        foreach (self::$fx['inSegment'] as $c) {
            $this->assertSame($c['result'], R::inSegment($c['client'], $c['segment'], $c['now'], $c['opts']), self::norm($c));
        }
        foreach (self::$fx['pick'] as $c) {
            $clients = array_unique(array_column(self::$fx['inSegment'], 'client'), SORT_REGULAR);
            $ids = array_column(R::pick(array_values($clients), $c['audience'], $c['now']), 'id');
            $this->assertSame($c['result'], $ids, self::norm($c['audience']));
        }
        foreach (self::$fx['reachable'] as $c) {
            $this->assertSame($c['result'], R::reachable($c['client']), self::norm($c['client']));
        }
    }

    public function test_clean_campaign_validation_matches_node_value_for_value(): void
    {
        $mismatch = [];
        foreach (self::$fx['clean'] as $i => $c) {
            $body = Json::decode(json_encode($c['body'], JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
            try {
                $got = ['result' => self::norm(R::cleanCampaign($body, $c['kind']))];
            } catch (ApiException $e) {
                $got = ['error' => $e->getMessage()];
            }
            if ($c['crash']) {
                // Node threw a TypeError here (the old API answered 500 "Server error"). Laravel must answer a clean 4xx instead.
                $this->assertArrayHasKey('error', $got, "#$i must be rejected");
                continue;
            }
            $want = isset($c['error']) ? ['error' => $c['error']] : ['result' => self::norm($c['result'])];
            if ($got !== $want) {
                $mismatch[] = "#$i {$c['kind']} ".self::norm($c['body'])."\n   node:    ".json_encode($want, JSON_UNESCAPED_UNICODE)."\n   laravel: ".json_encode($got, JSON_UNESCAPED_UNICODE);
            }
        }
        $this->assertSame([], $mismatch, implode("\n", $mismatch));
    }

    public function test_ready_requires_message_and_audience(): void
    {
        $ok = ['title' => ['fr' => 'a', 'ar' => '', 'dar' => ''], 'body' => ['fr' => 'b', 'ar' => '', 'dar' => ''], 'audience' => ['segments' => ['all'], 'clientIds' => []]];
        R::ready($ok, 'once');
        $this->assertTrue(true);
        foreach ([[['title' => ['fr' => '', 'ar' => '', 'dar' => '']] + $ok, 'MESSAGE_REQUIRED'], [['audience' => ['segments' => [], 'clientIds' => []]] + $ok, 'AUDIENCE_REQUIRED']] as [$data, $code]) {
            try {
                R::ready($data, 'once');
                $this->fail("expected $code");
            } catch (ApiException $e) {
                $this->assertSame($code, $e->getMessage());
            }
        }
        R::ready(['audience' => ['segments' => [], 'clientIds' => []]] + $ok, 'trigger'); // triggers need no audience
    }
}
